"""Random unsorted short intervals over a small range so overlaps, touches
and containments all occur."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(1, 8)
    pairs = []
    for _ in range(n):
        a = rng.randint(0, 20)
        pairs.append((a, a + rng.randint(0, 6)))
    return {"name": "%d intervals #%d" % (n, index),
            "stdin": "%d\n%s\n" % (n, "\n".join("%d %d" % p for p in pairs))}
